const sd = $getWorkflowStaticData('global');
sd.done = sd.done || [];

const num = n => parseInt((n.match(/\((\d+)\)/) || [0, 0])[1]);

const files = $input.all()
  .map(i => i.json)
  .filter(f => /\.mp4$/i.test(f.name))
  .sort((a, b) => num(a.name) - num(b.name));

const next = files.find(f => !sd.done.includes(f.id));
if (!next) return [];

return [{ json: { id: next.id, name: next.name, number: num(next.name) } }];

const raw = $input.first().json.text || $input.first().json.output || '';
let data = {};
try {
  data = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {}

const pick = $('Pick Next Video').first().json;

let title = (data.title || `GTA V Monster Truck Crash Chaos ${pick.number}`).trim();
if (title.length > 80) title = title.slice(0, 80).trim();

let tags = Array.isArray(data.hashtags) && data.hashtags.length
  ? data.hashtags
  : ['#shorts', '#gta5', '#gaming'];
tags = tags.map(t => t.startsWith('#') ? t : '#' + t).slice(0, 5);
if (!tags.map(t => t.toLowerCase()).includes('#shorts')) tags.unshift('#shorts');

return [{
  json: {
    id: pick.id,
    finalTitle: `${title} #Shorts`,
    description: `${data.description || 'Crazy GTA V crashes!'}\n\n${tags.join(' ')}`,
    tagList: tags.map(t => t.replace('#', '')).join(',')
  }
}];
